+            {
+                "tracking_id": "MpOl0QlTQ4SYYhEe6KgJoQ",
+                "tracking_started_at_millis": 1625558985010,
+                "routing": {
+                    "state": "STARTED",
+                    "primary": true,
+                    "node": "gA6KeeVzQkGURFCUyV-e8Q",
+                    "relocating_node": null
+                },
+                "stats" : {
+                    "all_fields": {
+                        "any": "6", <1>
+                        "inverted_index": {
+                            "terms" : 1,
+                            "postings" : 1,
+                            "proximity" : 1, <2>
+                            "positions" : 0,
+                            "term_frequencies" : 1,
+                            "offsets" : 0,
+                            "payloads" : 0
+                        },
+                        "stored_fields" : 2,
+                        "doc_values" : 1,
+                        "points" : 0,
+                        "norms" : 1,
+                        "term_vectors" : 0
+                    },
+                    "fields": {
+                        "_id": {
+                            "any" : 1,
+                            "inverted_index": {
+                                "terms" : 1,
