+
+    public String getPath() {
+        return path;
+    }
+
+    public String getFormat() {
+        return format;
+    }
+
+    public String getAlias() {
+        return alias;
+    }
+
+    public boolean hasPrivateKey() {
+        return hasPrivateKey;
+    }
