+        int remainder = maxDoc % getMax();
+        int quotient = maxDoc / getMax();
+
+        int sliceStart;
+        int sliceSize;
+        if (getId() < remainder) {
+            sliceStart = (quotient + 1) * getId();
+            sliceSize = quotient + 1;
+        } else {
+            sliceStart = remainder * (quotient + 1) + (getId() - remainder) * quotient;
+            sliceSize = quotient;
+        }
