+            new ShardSnapshotInfo(indexId, shardId, snapshot, indexMetadataIdentifier, shardStateIdentifier)
+        );
+    }
+
+    private Tuple<String, RepositoryException> repositoryFailure() {
+        String repositoryName = randomString(25);
