+                task.setInputFiles(yamlFiles);
+                task.setJsonSchema(new File(project.getRootDir(), RESOURCES + "changelog-schema.json"));
+                task.setReport(new File(project.getBuildDir(), "reports/validateYaml.txt"));
+            });
