+        final List<String> allLines;
+        try (InputStream in = response.getEntity().getContent()) {
+            allLines = Streams.readAllLines(in);
+        }
+        assertThat(allLines, Matchers.hasSize(snapshotsRepo1 + snapshotsRepo2));
